  }
} else if (servicio === 'Zonificación y Rutero') {
  if (!criterios.cantidad_registros) {
    return rechazar('criterios.cantidad_registros', 'Zonificación y Rutero requiere "cantidad_registros": "Preparar criterios para motor - Zonificación y Rutero" no envía tipo_organizacion, así que sin este dato el motor no puede contar empresas.');
  }
  if (!criterios.visitas_asesor) {
    return rechazar('criterios.visitas_asesor', 'Zonificación y Rutero requiere "visitas_asesor" (> 0): el motor lo exige para calcular el número de zonas.');
  }
  if (criterios.incluir_rutas === undefined || criterios.incluir_rutas === null || criterios.incluir_rutas === '') {
    return rechazar('criterios.incluir_rutas', 'Zonificación y Rutero requiere "incluir_rutas" (sí/no): el motor lo exige para calcular el valor de rutas.');
  }
} else if (servicio === 'Ubicación de Nuevo Negocio') {
  if (!criterios.cantidad_registros) {
    return rechazar('criterios.cantidad_registros', 'Ubicación de Nuevo Negocio requiere "cantidad_registros": "Preparar criterios para motor - Ubicación de Nuevo Negocio" no envía tipo_organizacion, así que sin este dato el motor no puede contar empresas.');
