  if (!criterios.niveles_analisis) {
    return rechazar('criterios.niveles_analisis', 'Ubicación de Nuevo Negocio requiere "niveles_analisis": el motor lo exige para calcular el número de niveles de análisis.');
  }
} else if (servicio === 'Información en Línea') {
  const planIndicado = (criterios.plan_en_linea || '').toString().trim();
  const tienePlan = planIndicado && planIndicado !== 'No estoy seguro / necesito ayuda';
