    criterios.consultas_mensuales !== undefined && criterios.consultas_mensuales !== null && criterios.consultas_mensuales !== '' &&
    criterios.usuarios !== undefined && criterios.usuarios !== null && criterios.usuarios !== '';
  if (!tienePlan && !tieneConsultasYUsuarios) {
    return rechazar('criterios.plan_en_linea', 'Información en Línea requiere "plan_en_linea" (un plan concreto) o, en su defecto, "consultas_mensuales" + "usuarios".');
  }
}

return { json: { ...$json, valido: true } };

