const idOriginal = $('Aplanar contrato de entrada').item.json.id_solicitud;
return { json: { ...$json, id_solicitud: idOriginal } };

// Validacion temprana de entrada (F2-01 extendido a W2A) -- corre ANTES de 'Aplanar contrato de
// entrada' para no escribir en Data Tables ni llamar al motor (W3) con datos incompletos.
// Campos minimos derivados de evidencia real: contrato de 'Recibir solicitud' (servicio/id_solicitud/
// criterios, ver 'Ejecutar Guardar-y-Cotizar' en W2C), 'Switch - Servicio Solicitado' (4 valores exactos, sin
// fallbackOutput -> lo que no matchea se pierde en silencio), y los checks duros de W3
// ('Calcular Conteo y Precio': Falta tipo_organizacion / visitas_por_asesor / incluye_rutas ambiguo /
// num_niveles / plan_deseado o consultas_mensuales+numero_usuarios).
const servicio = $json.servicio;
const idSolicitud = $json.id_solicitud;
const criterios = $json.criterios;

const SERVICIOS_VALIDOS = [
  'Información Georreferenciada',
  'Zonificación y Rutero',
  'Ubicación de Nuevo Negocio',
  'Información en Línea'
];

function rechazar(campo, mensaje) {
  return { json: { ...$json, valido: false, campo_faltante: campo, mensaje_error: mensaje } };
}

if (!idSolicitud) {
  return rechazar('id_solicitud', 'Falta "id_solicitud" en la solicitud recibida por el sub-workflow Guardar Criterios y Cotizar Servicio.');
}
if (!servicio || !SERVICIOS_VALIDOS.includes(servicio)) {
  return rechazar('servicio', 'El campo "servicio" ("' + (servicio || '(vacío)') + '") no coincide con ninguno de los 4 valores que reconoce "Switch - Servicio Solicitado": ' + SERVICIOS_VALIDOS.join(' / ') + '.');
}
if (!criterios || typeof criterios !== 'object' || Array.isArray(criterios) || Object.keys(criterios).length === 0) {
  return rechazar('criterios', 'Falta el objeto "criterios" (payload completo de la cotización) o llegó vacío.');
}

if (servicio === 'Información Georreferenciada') {
  if (!criterios.organizacion_juridica) {
    return rechazar('criterios.organizacion_juridica', 'Información Georreferenciada requiere "organizacion_juridica": sin ese dato, "Calcular Conteo y Precio" (W3) no puede filtrar la base de empresas (falla con "Falta tipo_organizacion").');
  }
} else if (servicio === 'Zonificación y Rutero') {
  if (!criterios.cantidad_registros) {
    return rechazar('criterios.cantidad_registros', 'Zonificación y Rutero requiere "cantidad_registros": "Preparar criterios para motor - Zonificación y Rutero" no envía tipo_organizacion, así que sin este dato el motor no puede contar empresas.');
  }
  if (!criterios.visitas_asesor) {
    return rechazar('criterios.visitas_asesor', 'Zonificación y Rutero requiere "visitas_asesor" (> 0): el motor lo exige para calcular el número de zonas.');
  }
  if (criterios.incluir_rutas === undefined || criterios.incluir_rutas === null || criterios.incluir_rutas === '') {
    return rechazar('criterios.incluir_rutas', 'Zonificación y Rutero requiere "incluir_rutas" (sí/no): el motor lo exige para calcular el valor de rutas.');
  }
} else if (servicio === 'Ubicación de Nuevo Negocio') {
  if (!criterios.cantidad_registros) {
    return rechazar('criterios.cantidad_registros', 'Ubicación de Nuevo Negocio requiere "cantidad_registros": "Preparar criterios para motor - Ubicación de Nuevo Negocio" no envía tipo_organizacion, así que sin este dato el motor no puede contar empresas.');
  }
  if (!criterios.niveles_analisis) {
    return rechazar('criterios.niveles_analisis', 'Ubicación de Nuevo Negocio requiere "niveles_analisis": el motor lo exige para calcular el número de niveles de análisis.');
  }
} else if (servicio === 'Información en Línea') {
  const planIndicado = (criterios.plan_en_linea || '').toString().trim();
  const tienePlan = planIndicado && planIndicado !== 'No estoy seguro / necesito ayuda';
  const tieneConsultasYUsuarios =
    criterios.consultas_mensuales !== undefined && criterios.consultas_mensuales !== null && criterios.consultas_mensuales !== '' &&
    criterios.usuarios !== undefined && criterios.usuarios !== null && criterios.usuarios !== '';
  if (!tienePlan && !tieneConsultasYUsuarios) {
    return rechazar('criterios.plan_en_linea', 'Información en Línea requiere "plan_en_linea" (un plan concreto) o, en su defecto, "consultas_mensuales" + "usuarios".');
  }
}

return { json: { ...$json, valido: true } };
